#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int num_threads = 1;
    std::vector<long long> blockSums;

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();

        #pragma omp single
        {
            num_threads = omp_get_num_threads();
            blockSums.assign(num_threads, 0LL);
        }

        const int chunk = (n + num_threads - 1) / num_threads;
        const int start = tid * chunk;
        const int end = (start + chunk < n) ? (start + chunk) : n;

        long long localSum = 0;
        if (start < n) {
            // Local reverse prefix within this block: from end-1 down to start
            for (int i = end - 1; i >= start; --i) {
                localSum += static_cast<long long>(x[i]);
                output[i] = static_cast<int>(localSum);
            }
        }
        blockSums[tid] = localSum;

        #pragma omp barrier

        long long offset = 0;
        for (int t = 0; t < tid; ++t) {
            offset += blockSums[t];
        }

        if (start < n && offset != 0) {
            for (int i = start; i < end; ++i) {
                output[i] = static_cast<int>(static_cast<long long>(output[i]) + offset);
            }
        }
    }
}
